 source_formulation=dict(text='The 2017 source formulates two-set 3SUM indexing and separates two hardness conjectures. The user-approved September 13 consolidation asks for the full space/query exponent curve in the fixed polynomial-universe model, keeping the previous threshold in formulation history.',citation='sets',caption='§3, Problem 3 and Conjectures 5–6; current algorithms in Dinur–Golovnev §1.3.',format='editorial_paraphrase'),
